local GloveMaker = {}
local PRODUCTS = {
    simple_wool_gloves = { name = "Preproste volnene rokavice", woolCost = 2, threadCost = 1, time = 3, cost = 40, warmth = 22, happiness = 1, description = "Preproste volnene rokavice za zimo." },
    leather_riding_gloves = { name = "Usnjene jahalne rokavice", leatherCost = 2, woolCost = 1, threadCost = 1, time = 5, cost = 120, warmth = 35, happiness = 1, prestige = 2, description = "Usnjene jahalne rokavice za trgovce." },
    silk_lined_gloves = { name = "Sviloobložene rokavice", leatherCost = 2, silkCost = 1, woolCost = 1, threadCost = 1, time = 8, cost = 300, warmth = 48, happiness = 2, prestige = 6, description = "Sviloobložene rokavice za plemiče." },
    silver_embroidered_gloves = { name = "Srebrnovezene rokavice", leatherCost = 2, silkCost = 1, silverCost = 1, woolCost = 1, threadCost = 1, time = 12, cost = 720, warmth = 60, happiness = 3, prestige = 14, description = "Srebrnovezene rokavice za visoke plemiče." },
    gold_trimmed_gloves = { name = "Zlatookrasne rokavice", leatherCost = 2, silkCost = 1, goldCost = 1, silverCost = 1, woolCost = 1, threadCost = 1, jewelCost = 1, time = 16, cost = 1600, warmth = 72, happiness = 5, prestige = 27, description = "Rokavice z zlato obrobo za visoko plemstvo." },
    royal_grand_gloves = { name = "Kraljevski velike rokavice", leatherCost = 3, silkCost = 2, goldCost = 2, silverCost = 2, woolCost = 1, threadCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3600, warmth = 88, happiness = 12, prestige = 58, description = "Velike kraljevske rokavice z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    glove_workshop = { name = "Rokavičarska delavnica", cost = { gold = 220, wood = 100, stone = 100, wool = 6, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    glover_loft = { name = "Rokavičarska podstrešje", cost = { gold = 880, wood = 240, stone = 220, silver = 6, silk = 6 }, upkeep = 20, qualityBonus = 18 },
    master_glover_atelier = { name = "Mojstrski rokavičarski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_glover_palace = { name = "Kraljevska rokavičarska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
GloveMaker.woolStock = 14; GloveMaker.leatherStock = 12; GloveMaker.silkStock = 10; GloveMaker.threadStock = 12; GloveMaker.silverStock = 6; GloveMaker.goldStock = 6; GloveMaker.jewelStock = 4; GloveMaker.pearlStock = 4
GloveMaker.productStock = {}; GloveMaker.buildings = {}; GloveMaker.maker = nil; GloveMaker.activeMaking = {}; GloveMaker.totalProducts = 0; GloveMaker.dayTimer = 0
function GloveMaker.init() GloveMaker.woolStock=14; GloveMaker.leatherStock=12; GloveMaker.silkStock=10; GloveMaker.threadStock=12; GloveMaker.silverStock=6; GloveMaker.goldStock=6; GloveMaker.jewelStock=4; GloveMaker.pearlStock=4; GloveMaker.productStock={}; GloveMaker.buildings={}; GloveMaker.maker=nil; GloveMaker.activeMaking={}; GloveMaker.totalProducts=0; GloveMaker.dayTimer=0; print("[GloveMaker] Royal Glove Maker System initialized (6 products, 4 buildings)") end
function GloveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GloveMaker.maker={name=n or ("Rokavičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rokavičar najet: %s (spretnost: %d)",GloveMaker.maker.name,s),"success") end; return true end
function GloveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GloveMaker.build(id) local ok,e=GloveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GloveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GloveMaker.getQualityBonus() local b=0; for _,bd in ipairs(GloveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GloveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woolCost and GloveMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.leatherCost and GloveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silkCost and GloveMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.threadCost and GloveMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and GloveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GloveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GloveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GloveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GloveMaker.buildings==0 then return false,"Potrebna rokavičarska delavnica" end; if not GloveMaker.maker then return false,"Potreben rokavičar" end; return true end
function GloveMaker.make(pt,qty) qty=qty or 1; local ok,e=GloveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woolCost then GloveMaker.woolStock=GloveMaker.woolStock-d.woolCost*qty end; if d.leatherCost then GloveMaker.leatherStock=GloveMaker.leatherStock-d.leatherCost*qty end; if d.silkCost then GloveMaker.silkStock=GloveMaker.silkStock-d.silkCost*qty end; if d.threadCost then GloveMaker.threadStock=GloveMaker.threadStock-d.threadCost*qty end; if d.silverCost then GloveMaker.silverStock=GloveMaker.silverStock-d.silverCost*qty end; if d.goldCost then GloveMaker.goldStock=GloveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GloveMaker.jewelStock=GloveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GloveMaker.pearlStock=GloveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GloveMaker.maker then t=math.max(1,t-math.floor(GloveMaker.maker.skill/13)) end; table.insert(GloveMaker.activeMaking,{id="glove_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,warmth=d.warmth or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GloveMaker.completeMaking(m) local q=1.0+(GloveMaker.getQualityBonus()/100); if GloveMaker.maker then q=q+(GloveMaker.maker.skill/140) end; q=math.min(2.5,q); GloveMaker.productStock[m.productType]=(GloveMaker.productStock[m.productType] or 0)+m.quantity; GloveMaker.totalProducts=GloveMaker.totalProducts+m.quantity; if m.warmth>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+math.floor(m.warmth/30)) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GloveMaker.maker then GloveMaker.maker.itemsMade=GloveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GloveMaker.maker.skill=math.min(100,GloveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rokavice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glove.completed",{productName=m.productName,warmth=m.warmth,prestige=m.prestige,happiness=m.happiness}) end end
function GloveMaker.update(dt) if not _G.state then return end; GloveMaker.dayTimer=GloveMaker.dayTimer+dt; if GloveMaker.dayTimer>=30 then GloveMaker.dayTimer=0; for i=#GloveMaker.activeMaking,1,-1 do local m=GloveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GloveMaker.completeMaking(m); table.remove(GloveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GloveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GloveMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GloveMaker.getStats() return {woolStock=GloveMaker.woolStock,leatherStock=GloveMaker.leatherStock,silkStock=GloveMaker.silkStock,threadStock=GloveMaker.threadStock,silverStock=GloveMaker.silverStock,goldStock=GloveMaker.goldStock,jewelStock=GloveMaker.jewelStock,pearlStock=GloveMaker.pearlStock,productStock=GloveMaker.productStock,numBuildings=#GloveMaker.buildings,hasMaker=GloveMaker.maker~=nil,makerName=GloveMaker.maker and GloveMaker.maker.name or "—",makerSkill=GloveMaker.maker and GloveMaker.maker.skill or 0,activeMaking=#GloveMaker.activeMaking,totalProducts=GloveMaker.totalProducts} end
return GloveMaker
